FUNCTION_BLOCK FB
VAR_INPUT
    openBtn   : BOOL;
    closeBtn  : BOOL;
    openLimit : BOOL;
    closeLimit: BOOL;
    obstacle  : BOOL;
END_VAR

VAR_OUTPUT
    motorUp   : BOOL := FALSE;
    motorDown : BOOL := FALSE;
    errorFlag : BOOL := FALSE;
END_VAR

VAR
    state         : INT := 0;  // 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT
    prevOpenBtn   : BOOL := FALSE;
    prevCloseBtn  : BOOL := FALSE;
    obstacleSeen  : BOOL := FALSE;
    nextState     : INT := 0;
END_VAR

VAR
    openBtnRising  : BOOL;
    closeBtnRising : BOOL;
END_VAR

openBtnRising  := openBtn AND NOT prevOpenBtn;
closeBtnRising := closeBtn AND NOT prevCloseBtn;

prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;

nextState := state;

CASE state OF
    0:  // IDLE
        motorUp   := FALSE;
        motorDown := FALSE;

        IF openBtnRising THEN
            obstacleSeen := FALSE;
        END_IF
        IF closeBtnRising THEN
            obstacleSeen := FALSE;
        END_IF

        IF openBtnRising AND NOT openLimit AND NOT obstacleSeen THEN
            nextState := 1;
        ELSIF closeBtnRising AND NOT closeLimit AND NOT obstacleSeen THEN
            nextState := 2;
        END_IF

    1:  // OPENING
        motorUp   := TRUE;
        motorDown := FALSE;

        IF obstacle THEN
            obstacleSeen := TRUE;
        END_IF

        IF openLimit THEN
            motorUp := FALSE;
            nextState := 0;
        ELSIF obstacle THEN
            motorUp := FALSE;
            errorFlag := TRUE;
            nextState := 3;
        END_IF

    2:  // CLOSING
        motorUp   := FALSE;
        motorDown := TRUE;

        IF obstacle THEN
            motorDown := FALSE;
            nextState := 1;
        ELSIF closeLimit THEN
            motorDown := FALSE;
            nextState := 0;
        END_IF

    3:  // FAULT
        motorUp   := FALSE;
        motorDown := FALSE;

        IF openBtnRising AND closeBtnRising THEN
            obstacleSeen := FALSE;
            errorFlag := FALSE;
            nextState := 0;
        END_IF
END_CASE

state := nextState;
END_FUNCTION_BLOCK

